import boto3

# Initialize the IAM client
iam = boto3.client('iam')

def create_identity(name):
    try:
        response = iam.create_user(UserName=name)
        print(f"Identity '{name}' created successfully.")
        return response['User']['UserName']
    except Exception as e:
        print(f"Failed to create identity: {e}")
        return None

def attach_policy_to_identity(identity_name, policy_arn):
    try:
        response = iam.attach_user_policy(
            UserName=identity_name,
            PolicyArn=policy_arn
        )
        print(f"Policy attached to identity '{identity_name}'.")
    except Exception as e:
        print(f"Failed to attach policy: {e}")

def list_policies_for_identity(identity_name):
    try:
        response = iam.list_attached_user_policies(
            UserName=identity_name
        )
        for policy in response.get('AttachedPolicies', []):
            print(policy['PolicyArn'])
    except Exception as e:
        print(f"Failed to list policies: {e}")

if __name__ == "__main__":
    # Example usage
    user_name = "my-user"
    policy_arn = "arn:aws:iam::123456789012:policy/my-policy"

    # Create a new user
    identity_name = create_identity(user_name)

    if identity_name:
        # Attach a policy to the user
        attach_policy_to_identity(identity_name, policy_arn)

        # List all policies associated with the user
        list_policies_for_identity(identity_name)
